--------------------------------------------------------
--  DDL FOR TABLE SIAC_PROG
--------------------------------------------------------
CREATE TABLE SIAC_PROG (
  COD_PROG    VARCHAR2(5)    NOT NULL,
  NOM_PROG    VARCHAR2(120)  NOT NULL,
  NIV_FORM    CHAR(1)        NOT NULL,
  COD_SNIES   NUMBER(8),
  NUM_SEM     NUMBER(2),
  EST_PROG    CHAR(1)        DEFAULT 'A' NOT NULL,
  FEC_CREA    DATE
);
COMMENT ON TABLE SIAC_PROG IS 'PROGRAMAS ACADEMICOS OFRECIDOS';
COMMENT ON COLUMN SIAC_PROG.COD_PROG IS 'CODIGO INTERNO DEL PROGRAMA';
COMMENT ON COLUMN SIAC_PROG.NIV_FORM IS 'NIVEL DE FORMACION: P=PREGRADO E=ESPECIALIZACION';
COMMENT ON COLUMN SIAC_PROG.COD_SNIES IS 'CODIGO SNIES DEL REGISTRO CALIFICADO';
COMMENT ON COLUMN SIAC_PROG.EST_PROG IS 'ESTADO DEL PROGRAMA: A=ACTIVO I=INACTIVO';

--------------------------------------------------------
--  DDL FOR TABLE SIAC_PER_ACAD
--------------------------------------------------------
CREATE TABLE SIAC_PER_ACAD (
  COD_PER      VARCHAR2(6)   NOT NULL,
  DES_PER      VARCHAR2(40),
  FEC_INI      DATE,
  FEC_FIN      DATE,
  IND_VIGENTE  CHAR(1)       DEFAULT 'N' NOT NULL
);
COMMENT ON TABLE SIAC_PER_ACAD IS 'PERIODOS ACADEMICOS';
COMMENT ON COLUMN SIAC_PER_ACAD.IND_VIGENTE IS 'S=PERIODO VIGENTE (SOLO UNO)';

--------------------------------------------------------
--  DDL FOR TABLE SIAC_PERS
--------------------------------------------------------
CREATE TABLE SIAC_PERS (
  ID_PERS    NUMBER(10)     NOT NULL,
  TIP_DOC    VARCHAR2(3)    NOT NULL,
  NUM_DOC    VARCHAR2(20)   NOT NULL,
  PRI_NOM    VARCHAR2(60)   NOT NULL,
  SEG_NOM    VARCHAR2(60),
  PRI_APE    VARCHAR2(60)   NOT NULL,
  SEG_APE    VARCHAR2(60),
  FEC_NAC    VARCHAR2(10),
  SEXO       CHAR(1),
  EMAIL      VARCHAR2(120),
  TEL_CEL    VARCHAR2(20),
  MUNICIPIO  VARCHAR2(60),
  FEC_REG    DATE           NOT NULL,
  USU_REG    VARCHAR2(20),
  IND_ANUL   CHAR(1)        DEFAULT 'N'
);
COMMENT ON TABLE SIAC_PERS IS 'PERSONAS: ASPIRANTES, ESTUDIANTES Y EGRESADOS';
COMMENT ON COLUMN SIAC_PERS.TIP_DOC IS 'TIPO DE DOCUMENTO: CC TI CE PPT';
COMMENT ON COLUMN SIAC_PERS.NUM_DOC IS 'NUMERO DE DOCUMENTO DE IDENTIDAD';
COMMENT ON COLUMN SIAC_PERS.FEC_NAC IS 'FECHA DE NACIMIENTO (DD/MM/AAAA)';
COMMENT ON COLUMN SIAC_PERS.USU_REG IS 'USUARIO QUE REGISTRA';

--------------------------------------------------------
--  DDL FOR TABLE SIAC_EST
--------------------------------------------------------
CREATE TABLE SIAC_EST (
  COD_EST      VARCHAR2(12)  NOT NULL,
  ID_PERS      NUMBER(10)    NOT NULL,
  COD_PROG     VARCHAR2(5)   NOT NULL,
  COD_PER_ING  VARCHAR2(6),
  EST_ESTADO   CHAR(1)       NOT NULL,
  FEC_ESTADO   DATE,
  FEC_GRADO    DATE,
  IND_ANUL     CHAR(1)       DEFAULT 'N'
);
COMMENT ON TABLE SIAC_EST IS 'ESTUDIANTES (UN REGISTRO POR PROGRAMA)';
COMMENT ON COLUMN SIAC_EST.COD_EST IS 'CODIGO DEL ESTUDIANTE: AAAAP + CONSECUTIVO';
COMMENT ON COLUMN SIAC_EST.COD_PER_ING IS 'PERIODO DE INGRESO';
COMMENT ON COLUMN SIAC_EST.EST_ESTADO IS 'A=ACTIVO I=INACTIVO R=RETIRADO G=GRADUADO';

--------------------------------------------------------
--  DDL FOR TABLE SIAC_ASIG
--------------------------------------------------------
CREATE TABLE SIAC_ASIG (
  COD_ASIG   VARCHAR2(10)   NOT NULL,
  NOM_ASIG   VARCHAR2(120)  NOT NULL,
  COD_PROG   VARCHAR2(5)    NOT NULL,
  NUM_SEM    NUMBER(2),
  CREDITOS   NUMBER(2)
);
COMMENT ON TABLE SIAC_ASIG IS 'ASIGNATURAS DEL PLAN DE ESTUDIOS';

--------------------------------------------------------
--  DDL FOR TABLE SIAC_MATR
--------------------------------------------------------
CREATE TABLE SIAC_MATR (
  ID_MATR    NUMBER(10)     NOT NULL,
  COD_EST    VARCHAR2(12)   NOT NULL,
  COD_PER    VARCHAR2(6)    NOT NULL,
  COD_PROG   VARCHAR2(5)    NOT NULL,
  NUM_SEM    NUMBER(2),
  FEC_MATR   DATE           NOT NULL,
  TIP_MATR   CHAR(1),
  EST_MATR   CHAR(1)        DEFAULT 'M',
  USU_REG    VARCHAR2(20),
  IND_ANUL   CHAR(1)        DEFAULT 'N'
);
COMMENT ON TABLE SIAC_MATR IS 'MATRICULA ACADEMICA POR PERIODO';
COMMENT ON COLUMN SIAC_MATR.TIP_MATR IS 'N=NUEVO A=ANTIGUO R=REINTEGRO';
COMMENT ON COLUMN SIAC_MATR.EST_MATR IS 'M=MATRICULADO C=CANCELADO';

--------------------------------------------------------
--  DDL FOR TABLE SIAC_CALIF
--------------------------------------------------------
CREATE TABLE SIAC_CALIF (
  ID_CALIF   NUMBER(12)     NOT NULL,
  ID_MATR    NUMBER(10)     NOT NULL,
  COD_ASIG   VARCHAR2(10)   NOT NULL,
  NOTA_C1    NUMBER(4,2),
  NOTA_C2    NUMBER(4,2),
  NOTA_C3    NUMBER(4,2),
  NOTA_DEF   NUMBER(4,2),
  FEC_REG    DATE,
  USU_REG    VARCHAR2(20),
  IND_ANUL   CHAR(1)        DEFAULT 'N'
);
COMMENT ON TABLE SIAC_CALIF IS 'CALIFICACIONES POR ASIGNATURA';
COMMENT ON COLUMN SIAC_CALIF.NOTA_C1 IS 'PRIMER CORTE (30%)';
COMMENT ON COLUMN SIAC_CALIF.NOTA_C2 IS 'SEGUNDO CORTE (30%)';
COMMENT ON COLUMN SIAC_CALIF.NOTA_C3 IS 'TERCER CORTE (40%)';
COMMENT ON COLUMN SIAC_CALIF.NOTA_DEF IS 'NOTA DEFINITIVA ESCALA 0.0 A 5.0';

