--------------------------------------------------------
--  TRIGGERS
--------------------------------------------------------
CREATE OR REPLACE TRIGGER TRG_SIAC_PERS_BI
BEFORE INSERT ON SIAC_PERS
FOR EACH ROW
BEGIN
  IF :NEW.ID_PERS IS NULL THEN
    SELECT SEQ_SIAC_PERS.NEXTVAL INTO :NEW.ID_PERS FROM DUAL;
  END IF;
  IF :NEW.FEC_REG IS NULL THEN
    :NEW.FEC_REG := SYSDATE;
  END IF;
END;
/

CREATE OR REPLACE TRIGGER TRG_SIAC_MATR_BI
BEFORE INSERT ON SIAC_MATR
FOR EACH ROW
BEGIN
  IF :NEW.ID_MATR IS NULL THEN
    SELECT SEQ_SIAC_MATR.NEXTVAL INTO :NEW.ID_MATR FROM DUAL;
  END IF;
END;
/

--------------------------------------------------------
--  PACKAGE PKG_ESTADO_ESTUDIANTE
--------------------------------------------------------
CREATE OR REPLACE PACKAGE PKG_ESTADO_ESTUDIANTE AS
  /* ************************************************************
     PAQUETE     : PKG_ESTADO_ESTUDIANTE
     DESCRIPCION : CALCULO DEL ESTADO ACADEMICO DEL ESTUDIANTE
     AUTOR       : JCMEJIA          FECHA: 14/03/2014
     MODIFICADO  : JCMEJIA 02/08/2016 RESERVA DE CUPO (ACUERDO 07/2016)
     USADO POR   : VW_ESTUDIANTES_ACTIVOS, INFORMES DE DIRECCION
     ************************************************************ */
  FUNCTION FN_PERIODO_VIGENTE RETURN VARCHAR2;
  FUNCTION FN_PERIODO_ANTERIOR (P_COD_PER IN VARCHAR2) RETURN VARCHAR2;
  FUNCTION FN_ESTADO (P_COD_EST IN VARCHAR2) RETURN VARCHAR2;
END PKG_ESTADO_ESTUDIANTE;
/

CREATE OR REPLACE PACKAGE BODY PKG_ESTADO_ESTUDIANTE AS

  -- RETORNA EL PERIODO MARCADO COMO VIGENTE EN SIAC_PER_ACAD
  FUNCTION FN_PERIODO_VIGENTE RETURN VARCHAR2 IS
    V_COD_PER SIAC_PER_ACAD.COD_PER%TYPE;
  BEGIN
    SELECT COD_PER INTO V_COD_PER
      FROM SIAC_PER_ACAD
     WHERE IND_VIGENTE = 'S';
    RETURN V_COD_PER;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RETURN NULL;
    WHEN TOO_MANY_ROWS THEN
      SELECT MAX(COD_PER) INTO V_COD_PER FROM SIAC_PER_ACAD WHERE IND_VIGENTE = 'S';
      RETURN V_COD_PER;
  END FN_PERIODO_VIGENTE;

  -- PERIODO ANTERIOR: 2026-2 -> 2026-1, 2026-1 -> 2025-2
  FUNCTION FN_PERIODO_ANTERIOR (P_COD_PER IN VARCHAR2) RETURN VARCHAR2 IS
  BEGIN
    IF P_COD_PER IS NULL THEN
      RETURN NULL;
    END IF;
    IF SUBSTR(P_COD_PER, 6, 1) = '2' THEN
      RETURN SUBSTR(P_COD_PER, 1, 4) || '-1';
    ELSE
      RETURN TO_CHAR(TO_NUMBER(SUBSTR(P_COD_PER, 1, 4)) - 1) || '-2';
    END IF;
  END FN_PERIODO_ANTERIOR;

  /* ESTADOS: ACTIVO / INACTIVO / RETIRADO / GRADUADO / NO EXISTE
     ACTIVO: TIENE MATRICULA EN EL PERIODO VIGENTE O EN EL INMEDIATAMENTE
     ANTERIOR (RESERVA DE CUPO). EL ESTUDIANTE CONSERVA EL CUPO UN PERIODO. */
  FUNCTION FN_ESTADO (P_COD_EST IN VARCHAR2) RETURN VARCHAR2 IS
    V_ESTADO   SIAC_EST.EST_ESTADO%TYPE;
    V_FEC_GRA  SIAC_EST.FEC_GRADO%TYPE;
    V_PER_VIG  VARCHAR2(6);
    V_PER_ANT  VARCHAR2(6);
    V_CNT      NUMBER := 0;
  BEGIN
    SELECT EST_ESTADO, FEC_GRADO
      INTO V_ESTADO, V_FEC_GRA
      FROM SIAC_EST
     WHERE COD_EST = P_COD_EST;

    IF V_FEC_GRA IS NOT NULL THEN
      RETURN 'GRADUADO';
    END IF;

    IF V_ESTADO = 'R' THEN
      RETURN 'RETIRADO';
    END IF;

    V_PER_VIG := FN_PERIODO_VIGENTE;
    V_PER_ANT := FN_PERIODO_ANTERIOR(V_PER_VIG);

    SELECT COUNT(1)
      INTO V_CNT
      FROM SIAC_MATR M
     WHERE M.COD_EST = P_COD_EST
       AND M.COD_PER IN (V_PER_VIG, V_PER_ANT);

    IF V_CNT > 0 THEN
      RETURN 'ACTIVO';
    END IF;

    RETURN 'INACTIVO';
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RETURN 'NO EXISTE';
  END FN_ESTADO;

END PKG_ESTADO_ESTUDIANTE;
/

--------------------------------------------------------
--  VIEWS
--------------------------------------------------------
CREATE OR REPLACE VIEW VW_ESTUDIANTES_ACTIVOS AS
SELECT E.COD_EST, E.ID_PERS, E.COD_PROG, P.NOM_PROG, E.COD_PER_ING
  FROM SIAC_EST E
  JOIN SIAC_PROG P ON P.COD_PROG = E.COD_PROG
 WHERE PKG_ESTADO_ESTUDIANTE.FN_ESTADO(E.COD_EST) = 'ACTIVO';

COMMIT;
SET FEEDBACK ON
